  vocabulaire: {
    title: "Le vocabulaire de l'investissement",
    searchPlaceholder: "Rechercher un mot…",
    empty: "Aucun mot ne correspond à ta recherche.",
    close: "Fermer",
    terms: [
      { t: "Action", d: "Une part de propriété d'une entreprise. En détenir une fait de toi un actionnaire, avec une toute petite fraction de ses résultats." },
      { t: "Assurance-vie", d: "Une enveloppe d'épargne française, souple et fiscalement avantageuse après huit ans. Elle peut contenir des fonds sécurisés comme des placements plus risqués." },
      { t: "Capitalisation boursière", d: "La valeur totale d'une entreprise en bourse : son cours multiplié par le nombre d'actions. Elle mesure sa taille, pas sa performance." },
      { t: "CTO", d: "Compte-Titres Ordinaire. Un compte d'investissement sans plafond ni restriction géographique, mais sans avantage fiscal particulier." },
      { t: "Diversification", d: "Répartir son argent sur plusieurs placements pour qu'un seul incident ne mette pas tout en danger." },
      { t: "Dividende", d: "Une part des bénéfices qu'une entreprise reverse à ses actionnaires, souvent une fois par an. Toutes n'en versent pas." },
      { t: "ETF", d: "Un fonds coté en bourse qui réplique un indice. Acheter une part revient à investir d'un coup dans des centaines d'entreprises." },
      { t: "Frais de courtage", d: "Ce que ton intermédiaire prélève à chaque achat ou vente. Faibles en apparence, ils pèsent lourd sur le long terme." },
      { t: "Indice", d: "Un panier d'entreprises servant de baromètre à un marché. Le CAC 40 suit les 40 plus grandes entreprises françaises cotées." },
      { t: "Inflation", d: "La hausse générale des prix. Elle réduit chaque année ce que ton argent permet d'acheter s'il dort sans rien rapporter." },
      { t: "Intérêts composés", d: "Quand tes gains produisent eux-mêmes des gains. C'est ce qui rend le temps aussi précieux quand on commence tôt." },
      { t: "Krach", d: "Une chute brutale et rapide des marchés. Elle fait partie de leur histoire et finit toujours par être suivie d'une reprise." },
      { t: "Liquidité", d: "La facilité à revendre un placement rapidement sans brader son prix. Une action cotée est liquide, un bien immobilier ne l'est pas." },
      { t: "Obligation", d: "Un prêt que tu consens à un État ou une entreprise, qui te rembourse avec des intérêts. Moins risqué qu'une action, et moins rémunérateur." },
      { t: "Ordre", d: "L'instruction d'achat ou de vente envoyée à ton intermédiaire. Au prix du marché, ou à un prix que tu fixes toi-même." },
      { t: "PEA", d: "Plan d'Épargne en Actions. Une enveloppe française réservée aux actions européennes, fiscalement très avantageuse après cinq ans." },
      { t: "Plus-value", d: "Le gain réalisé en revendant plus cher que le prix d'achat. Tant que tu n'as pas vendu, elle reste théorique." },
      { t: "Portefeuille", d: "L'ensemble de tes placements. Sa composition compte davantage que le choix d'une ligne en particulier." },
      { t: "Rendement", d: "Ce que rapporte un placement sur une période, exprimé en pourcentage. Un rendement passé ne garantit jamais le futur." },
      { t: "Volatilité", d: "L'ampleur des variations d'un placement. Plus elle est forte, plus la valeur monte et descend rapidement." },
    ],
  },

