  vocabulaire: {
    title: "The vocabulary of investing",
    searchPlaceholder: "Search for a word…",
    empty: "No word matches your search.",
    close: "Close",
    terms: [
      { t: "Share", d: "A unit of ownership in a company. Holding one makes you a shareholder, entitled to a tiny fraction of its results." },
      { t: "Life insurance (assurance-vie)", d: "A flexible French savings wrapper, tax-advantaged after eight years. It can hold safe funds as well as riskier investments." },
      { t: "Market capitalisation", d: "A company's total stock market value: its share price times the number of shares. It measures size, not performance." },
      { t: "CTO (securities account)", d: "An ordinary securities account. No cap, no geographic limit, but no particular tax advantage either." },
      { t: "Diversification", d: "Spreading your money across several investments so that a single setback cannot jeopardise everything." },
      { t: "Dividend", d: "A share of profits a company pays back to its shareholders, often once a year. Not every company pays one." },
      { t: "ETF", d: "An exchange-traded fund tracking an index. Buying one unit means investing in hundreds of companies at once." },
      { t: "Brokerage fees", d: "What your broker charges on each purchase or sale. They look small, yet they weigh heavily over the long run." },
      { t: "Index", d: "A basket of companies used as a market barometer. The CAC 40 tracks the 40 largest listed French companies." },
      { t: "Inflation", d: "The general rise in prices. Each year it reduces what your money can buy if it sits idle earning nothing." },
      { t: "Compound interest", d: "When your gains generate gains of their own. It is what makes time so valuable when you start early." },
      { t: "Crash", d: "A sharp, sudden market fall. It is part of market history and has always been followed by a recovery." },
      { t: "Liquidity", d: "How easily an investment can be sold quickly without slashing its price. A listed share is liquid, a property is not." },
      { t: "Bond", d: "A loan you make to a state or a company, repaid with interest. Less risky than a share, and less rewarding." },
      { t: "Order", d: "The buy or sell instruction sent to your broker. Either at the market price, or at a price you set yourself." },
      { t: "PEA (equity savings plan)", d: "A French wrapper reserved for European shares, highly tax-advantaged after five years." },
      { t: "Capital gain", d: "The profit made by selling above your purchase price. Until you sell, it remains theoretical." },
      { t: "Portfolio", d: "The whole of your investments. Its overall make-up matters more than any single holding." },
      { t: "Return", d: "What an investment earns over a period, as a percentage. Past returns never guarantee future ones." },
      { t: "Volatility", d: "How widely an investment swings. The higher it is, the faster the value rises and falls." },
    ],
  },

