  vocabulaire: {
    title: "El vocabulario de la inversión",
    searchPlaceholder: "Buscar una palabra…",
    empty: "Ninguna palabra coincide con tu búsqueda.",
    close: "Cerrar",
    terms: [
      { t: "Acción", d: "Una parte de la propiedad de una empresa. Tener una te convierte en accionista, con una pequeña fracción de sus resultados." },
      { t: "Seguro de vida (assurance-vie)", d: "Un producto de ahorro francés, flexible y ventajoso fiscalmente tras ocho años. Puede contener fondos seguros o inversiones más arriesgadas." },
      { t: "Capitalización bursátil", d: "El valor total de una empresa en bolsa: su cotización por el número de acciones. Mide su tamaño, no su rendimiento." },
      { t: "CTO (cuenta de valores)", d: "Una cuenta de inversión sin límite ni restricción geográfica, pero sin ventaja fiscal particular." },
      { t: "Diversificación", d: "Repartir el dinero entre varias inversiones para que un solo contratiempo no lo ponga todo en peligro." },
      { t: "Dividendo", d: "Una parte de los beneficios que una empresa reparte entre sus accionistas, a menudo una vez al año. No todas lo pagan." },
      { t: "ETF", d: "Un fondo cotizado que replica un índice. Comprar una participación equivale a invertir de golpe en cientos de empresas." },
      { t: "Comisiones de corretaje", d: "Lo que cobra tu intermediario en cada compra o venta. Parecen pequeñas, pero pesan mucho a largo plazo." },
      { t: "Índice", d: "Una cesta de empresas que sirve de barómetro de un mercado. El CAC 40 sigue a las 40 mayores empresas francesas cotizadas." },
      { t: "Inflación", d: "La subida general de los precios. Cada año reduce lo que tu dinero permite comprar si no genera nada." },
      { t: "Interés compuesto", d: "Cuando tus ganancias generan a su vez ganancias. Es lo que hace tan valioso el tiempo cuando empiezas pronto." },
      { t: "Crac", d: "Una caída brusca y rápida de los mercados. Forma parte de su historia y siempre ha ido seguida de una recuperación." },
      { t: "Liquidez", d: "La facilidad para vender una inversión rápidamente sin malvender. Una acción cotizada es líquida, un inmueble no." },
      { t: "Bono", d: "Un préstamo que concedes a un Estado o una empresa, que te devuelve con intereses. Menos arriesgado que una acción, y menos rentable." },
      { t: "Orden", d: "La instrucción de compra o venta enviada a tu intermediario. Al precio de mercado, o a un precio que fijas tú." },
      { t: "PEA (plan de ahorro en acciones)", d: "Un producto francés reservado a las acciones europeas, muy ventajoso fiscalmente tras cinco años." },
      { t: "Plusvalía", d: "La ganancia obtenida al vender por encima del precio de compra. Mientras no vendas, sigue siendo teórica." },
      { t: "Cartera", d: "El conjunto de tus inversiones. Su composición importa más que la elección de un valor concreto." },
      { t: "Rentabilidad", d: "Lo que produce una inversión en un periodo, en porcentaje. Una rentabilidad pasada nunca garantiza la futura." },
      { t: "Volatilidad", d: "La amplitud de las variaciones de una inversión. Cuanto mayor es, más rápido sube y baja su valor." },
    ],
  },

